// Monta a linha da aba Aprovacao. MODO ('p2' | 'humano') é injetado pelo build.py.
const PASSOS = ['ENVIAR_LINK', 'AGENDAR', 'TIRAR_DUVIDA'];
const deP2 = MODO === 'p2';
